(7438284, 1176013, 65234, '<td valign="top">Great focus, beautiful bokeh.</td>', 'Great focus, beautiful bokeh.', '2016-02-19 12:08:53.000000', NULL, 1),
(7438285, 1175966, 65234, '<td valign="top">Like the old-time feel to this.</td>', 'Like the old-time feel to this.', '2016-02-19 12:09:33.000000', NULL, 1),
(7438288, 1176167, 65234, '<td valign="top">The gold/silver progression makes this really interesting to me. Much more so than I would expect for the subject. Well done.</td>', 'The gold/silver progression makes this really interesting to me. Much more so than I would expect for the subject. Well done.', '2016-02-19 12:11:04.000000', NULL, 1),
(7438291, 1176060, 65234, '<td valign="top">I SO wanted to get a snowflake picture for this challenge, but didn''t get anything useful. Kudos on a tough capture!</td>', 'I SO wanted to get a snowflake picture for this challenge, but didn''t get anything useful. Kudos on a tough capture!', '2016-02-19 12:11:52.000000', NULL, 1),
(7438295, 1176147, 65234, '<td valign="top">Cool plant! I''m guessing all those drops are something sticky to trap insects with. Well captured.</td>', 'Cool plant! I''m guessing all those drops are something sticky to trap insects with. Well captured.', '2016-02-19 12:13:09.000000', NULL, 1),
(7438305, 1176213, 65234, '<td valign="top">A wee jumping spider! Although he may actually be fairly large for a jumping spider. I think their faces are just adorable.  If I had the detail, I might have cropped this much tighter on the bottom, if only because the rock he''s on is good camouflage. But very nice capture of the spider.</td>', 'A wee jumping spider! Although he may actually be fairly large for a jumping spider. I think their faces are just adorable.  If I had the detail, I might have cropped this much tighter on the bottom, if only because the rock he''s on is good camouflage. But very nice capture of the spider.', '2016-02-19 12:21:34.000000', NULL, 1),
(7438306, 1176010, 65234, '<td valign="top">Macros in a breeze are tough; kudos on this one isolating those little grains of grass.</td>', 'Macros in a breeze are tough; kudos on this one isolating those little grains of grass.', '2016-02-19 12:22:11.000000', NULL, 1),
